  const fehlt = pflicht.filter((k) => a[k] == null);
  const kat = ["Fläche & Pacht", "Agri-PV & Landwirtschaft", "Investieren & Projektbörse", "Recht & Genehmigung", "Strom, Markt & Gemeinschaft"];
  const bilder = ["solarpark-himmel", "solarpark-reihen", "solarpark-baeume", "freiflaeche-begehung", "investoren-vor-ort", "montage-freiflaeche", "planer-tablet", "pv-wind-abend", "module-sonne", "module-raster", "floating-pv", "floating-pv-montage", "gewerbedach", "dach-drohne", "techniker", "team-praesentation", "firmensitz", "speicher"].map((b) => `/img/${b}.jpg`);
  if (a.slug !== slug) out.push(`slug != Dateiname (${a.slug})`);
  if (fehlt.length) out.push("Pflichtfelder fehlen: " + fehlt.join(", "));
  if (w < 1800 || w > 3000) out.push(`Wortzahl ${w} (Soll 1.800–3.000)`);
  if (tab < 2) out.push(`nur ${tab} Tabelle(n)`);
  if (!a.faq || a.faq.length < 4) out.push(`FAQ ${a.faq?.length ?? 0} (< 4)`);
  const q = a.quellen || [];
  if (q.length < 4 || q.length > 8) out.push(`Quellen ${q.length} (Soll 4–8)`);
  if (q.some((x) => !x.stand || !/^https?:\/\//.test(x.url || ""))) out.push("Quelle ohne Stand/URL");
  if (intern.length < 8) out.push(`nur ${intern.length} verschiedene interne Links im Text (Soll ≥ 8)`);
  kaputt.forEach((k) => out.push("LINK: " + k));
  if (!kat.includes(a.kategorie)) out.push("Kategorie ungültig: " + a.kategorie);
  if (!bilder.includes(a.bild)) out.push("Bild nicht erlaubt: " + a.bild);
  if ((a.seoTitle || "").length > 60) out.push(`seoTitle ${a.seoTitle.length} Z. (> 60)`);
  if (a.description && (a.description.length < 140 || a.description.length > 160)) out.push(`description ${a.description.length} Z. (140–160)`);
  if (a.title && (a.title.length < 45 || a.title.length > 75)) out.push(`title ${a.title.length} Z.`);
  const ids = (a.abschnitte || []).map((s) => s.id);
  if (new Set(ids).size !== ids.length) out.push("doppelte Abschnitts-IDs");
  const txt = JSON.stringify(a);
