  console.log(`${out.length ? "✗" : "✓"} ${slug}: ${w} Wörter, ${tab} Tabellen, ${a.faq?.length} FAQ, ${q.length} Quellen, ${intern.length} Links${out.length ? "\n   - " + out.join("\n   - ") : ""}`);
  if (out.length) fehlerGesamt++;
}
process.exit(fehlerGesamt ? 1 : 0);

