const NPV3 = npv(r, V3);
const NPV3_PPA = npv(r, V3_PPA);
const IRR_D2 = irr(differenz(V2, V1(SPEZ_ALT.basis)));
const IRR_D2_SCHWACH = irr(differenz(V2, V1(SPEZ_ALT.schwach)));
